record.field:
log("ticket rule fired: %s" % records.ids)
for ticket in records:
    task = ticket.task_id
    partner = ticket.partner_id
    if task and partner and partner == task.project_id.partner_id:
        task.message_subscribe(partner_ids=partner.ids)
    project_partner = task.project_id.partner_id
    if project_partner and project_partner == partner:
        ticket.message_subscribe(partner_ids=partner.ids)
